import sys,pathlib,runpy,json
p=pathlib.Path(sys.argv[1]).absolute();root=p.parent
stdlib=pathlib.Path(sys.base_prefix)/'lib'/('python'+str(sys.version_info.major)+'.'+str(sys.version_info.minor))
events={'private_open':0,'DB_network_process':0,'package_reads':0,'stdlib_reads':0}
def audit(event,args):
    if event=='open' and not isinstance(args[0],int):
        target=pathlib.Path(args[0]).absolute()
        if target.is_relative_to(root):events['package_reads']+=1
        elif target.is_relative_to(stdlib):events['stdlib_reads']+=1
        else:
            events['private_open']+=1;raise RuntimeError('external host read refused: '+str(target))
    if event in {'sqlite3.connect','socket.__new__','subprocess.Popen','os.system'}:
        events['DB_network_process']+=1;raise RuntimeError('external execution refused')
sys.addaudithook(audit)
runpy.run_path(str(p),run_name='__main__')
print(json.dumps({'audit_events':events}))
